function savePayrollProfiles(array $data): array {
    $code = trim($data['code'] ?? '');
    $existing = supabase_get(SB_API . 'm_payroll_profiles?select=id&code=eq.' . urlencode($code) . '&limit=1');
    if (!empty($existing)) {
        http_response_code(409);
        return ['error' => "Code '{$code}' already exists."];
    }

    $ref = consumeNextReference('payroll_profiles');

    return supabase_post(SB_API . 'm_payroll_profiles', [
        'ref' => $ref,
        'code' => $data['code'] ?? '',
        'name' => $data['name'] ?? '',
        'currency_ref' => !empty($data['currency_ref']) ? $data['currency_ref'] : null,
        'pay_frequency' => $data['pay_frequency'] ?? '',
        'pay_day' => $data['pay_day'] ?? 0,
        'proration_method' => $data['proration_method'] ?? '',
        'fixed_divisor' => $data['fixed_divisor'] ?? 0,
        'remarks' => $data['remarks'] ?? '',
        'created_by' => current_user()['ref'] ?? null,
        'updated_by' => current_user()['ref'] ?? null,
    ]);
}

function updatePayrollProfiles(array $data): array {
    $ref = trim($data['ref'] ?? '');
    if ($ref === '' || !recordExists('m_payroll_profiles', $ref)) {
        return ['error' => 'Record not found.'];
    }

    return supabase_patch(SB_API . 'm_payroll_profiles?ref=eq.' . urlencode($ref), [
        'code' => $data['code'] ?? '',
        'name' => $data['name'] ?? '',
        'currency_ref' => !empty($data['currency_ref']) ? $data['currency_ref'] : null,
        'pay_frequency' => $data['pay_frequency'] ?? '',
