        'proration_method' => $data['proration_method'] ?? '',
        'fixed_divisor' => $data['fixed_divisor'] ?? 0,
        'remarks' => $data['remarks'] ?? '',
        'updated_by' => current_user()['ref'] ?? null,
    ]);
}

